import {hero,linkStatus} from './engine.mjs?v=6';
import {TEAM_LINKS,LINK_CHARGE,teamLinks,heroLinks} from './team-links.mjs?v=6';
const names=link=>link.members.map(id=>hero(id).name).join(' + ');
const faces=link=>`<div class="bond-faces">${link.members.map(id=>`<img src="/assets/${id}.jpg" alt="${hero(id).name}">`).join('')}<span>✦</span></div>`;
export function draftBonds(ids){const links=teamLinks(ids);return links.length?`<div class="draft-bonds"><span>İKİLİ YETENEKLER</span>${links.map(l=>`<b title="${l.desc}">✦ ${l.name}</b>`).join('')}</div>`:'';}
export function heroBonds(id){const links=heroLinks(id);return links.length?`<section class="hero-bonds" aria-label="Karakterin ikili yetenekleri"><span class="eyebrow">BİRLİKTE DAHA GÜÇLÜ</span>${links.map(l=>`<div class="hero-bond" style="--bond-color:${l.color}">${faces(l)}<div><b>${l.name}</b><small>${l.relation}</small><p>${l.desc}</p></div></div>`).join('')}<p class="bond-rule">İkisi de aynı takımda ve hayatta olmalı. Her ortak saldırı +1 yük; ${LINK_CHARGE} yükte sonraki isabetle otomatik ikili hamle. Kaçışta yük harcanmaz.</p></section>`:'';}
export function bondGuide(){return `<details class="bond-guide"><summary><span>✦ MARVEL BAĞLARI</span><b>${TEAM_LINKS.length} özel ikiliyi keşfet</b><small>Takımını bu eşleşmelere göre kur.</small></summary><div class="bond-guide-grid">${TEAM_LINKS.map(l=>`<article style="--bond-color:${l.color}">${faces(l)}<b>${l.name}</b><small>${names(l)}</small><p>${l.desc}</p><span>${l.relation}</span></article>`).join('')}</div><p class="bond-rule">İlişkiler Marvel hikâyelerinden ilham alır. Yetenek adları ve etkileri bu oyuna özel tasarlanmıştır.</p></details>`;}
export function bondDeck(game,battle,esc){return `<section class="bond-deck" aria-label="Takımların ikili yetenekleri"><div class="bond-deck-heading"><span class="eyebrow">TAKIMININ HİKÂYESİ</span><h2>Bağ kur. Birlikte vur.</h2><p>İki kahraman da hayattayken her ortak saldırı +1 yük. ${LINK_CHARGE} yükte isabetli saldırı, ikili yeteneğe dönüşür.</p></div><div class="bond-sides">${game.players.map((p,side)=>{const links=battle?linkStatus(battle,side):teamLinks(p.team).map(l=>({...l,charge:0,uses:0,active:true}));return `<div class="bond-side side-${side}"><h3>${esc(p.name)}</h3>${links.length?links.map(l=>`<article class="bond-card ${!l.active?'broken':l.charge===LINK_CHARGE?'charged':''}" style="--bond-color:${l.color}" data-bond="${l.id}" data-side="${side}">${faces(l)}<div><b>${l.name}</b><small>${names(l)}</small><p>${l.desc}</p><div class="bond-charge">${Array.from({length:LINK_CHARGE},(_,i)=>`<i class="${i<l.charge?'filled':''}"></i>`).join('')}<span>${!l.active?'BAĞ KOPTU':!battle?'ARENA İÇİN HAZIR':l.charge===LINK_CHARGE?'İKİLİ HAMLE HAZIR':l.charge+' / '+LINK_CHARGE+' YÜK'}${l.uses?' · '+l.uses+' KEZ':''}</span></div></div></article>`).join(''):`<p class="bond-empty">Bu takımda özel bir ikili yok. Grup uyumu ve kişisel yetenekler çalışmaya devam eder.</p>`}</div>`;}).join('')}</div></section>`;}
